import type { DictionaryEntry } from '../types/game';

// Helper to normalize level names to match the JSON filenames generated by the split script
export const normalizeLevelFilename = (level: string): string => {
  return String(level).toLowerCase().trim().replace(/[\s_-]+/g, '_');
};

/**
 * Fetch vocabulary entries for a specific level.
 */
export const fetchLevelData = async (level: string): Promise<DictionaryEntry[]> => {
  try {
    const filename = normalizeLevelFilename(level);
    const res = await fetch(`/data/levels/${filename}.json`);
    if (!res.ok) {
      throw new Error(`Failed to fetch level data: ${res.statusText}`);
    }
    return await res.json();
  } catch (error) {
    console.error('Error fetching level data:', error);
    return [];
  }
};

